-- M0 schema (SQLite). Tenant isolation is app-level (customer_id on every
-- tenant-scoped table) per Review Decisions #3. IDs and timestamps are
-- generated by column DEFAULT expressions so application INSERTs are
-- unchanged from the Postgres version (no gen_random_uuid()/now() in SQLite,
-- so these defaults replicate them).
-- UUID default: a v4-shaped UUID built from random blobs.
-- Timestamp default: ISO-8601 UTC, matching what the frontend already parses.

CREATE TABLE customers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Roles modeled now; real login/session enforcement deferred (Review Decisions #1).
CREATE TABLE users (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  email TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL CHECK (role IN ('super_admin', 'customer_admin', 'fleet_manager', 'viewer')) DEFAULT 'viewer',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE projects (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE fleets (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- 'signal_lost' added per Review Decisions #5: a truck that stops reporting
-- must be distinguishable from idle/breakdown.
CREATE TABLE trucks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  fleet_id TEXT NOT NULL REFERENCES fleets(id),
  truck_number TEXT NOT NULL,
  capacity_tons REAL,
  status TEXT NOT NULL CHECK (status IN ('available', 'working', 'idle', 'under_maintenance', 'breakdown', 'signal_lost', 'out_of_service')) DEFAULT 'available',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE drivers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  fleet_id TEXT NOT NULL REFERENCES fleets(id),
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE INDEX idx_projects_customer ON projects(customer_id);
CREATE INDEX idx_fleets_customer ON fleets(customer_id);
CREATE INDEX idx_trucks_customer ON trucks(customer_id);
CREATE INDEX idx_trucks_fleet ON trucks(fleet_id);
CREATE INDEX idx_drivers_customer ON drivers(customer_id);
